  "bestCut.consent": "Para encontrar sua melhor tomada, os arquivos de vídeo selecionados são enviados inteiros à Veyrnox.ai e a um serviço de transcrição para ler o áudio. O roteiro e as notas ficam neste telefone. Os envios temporários de transcrição têm exclusão programada após 24 horas; a limpeza pode demorar mais. As transcrições ficam armazenadas por até 30 dias para evitar cobrança duplicada. Excluir a conta remove as transcrições. Os originais da biblioteca e backups de projetos seguem seus próprios ciclos. Se ninguém falar, nada será cobrado.",
